from docx import Document
from docx.shared import Inches, Pt, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
from docx.enum.table import WD_TABLE_ALIGNMENT, WD_CELL_VERTICAL_ALIGNMENT

path='output/spa-markup-memorandum.docx'
doc=Document(path)
for sec in doc.sections:
    sec.top_margin=Inches(0.75); sec.bottom_margin=Inches(0.72); sec.left_margin=Inches(0.85); sec.right_margin=Inches(0.75)
    sec.header_distance=Inches(0.35); sec.footer_distance=Inches(0.35)
    hp=sec.header.paragraphs[0]; hp.text='CONFIDENTIAL — ATTORNEY WORK PRODUCT | PROJECT CASCADE'; hp.alignment=WD_ALIGN_PARAGRAPH.RIGHT
    for r in hp.runs:
        r.font.name='Arial'; r.font.size=Pt(8); r.font.color.rgb=RGBColor(90,90,90)
    fp=sec.footer.paragraphs[0]; fp.alignment=WD_ALIGN_PARAGRAPH.CENTER; fp.text='SPA Markup Memorandum  •  '
    run=fp.add_run(); fld=OxmlElement('w:fldSimple'); fld.set(qn('w:instr'),'PAGE'); run._r.addnext(fld)
    for r in fp.runs:
        r.font.name='Arial'; r.font.size=Pt(8); r.font.color.rgb=RGBColor(90,90,90)
styles=doc.styles
for name in ['Normal','Body Text']:
    if name in styles:
        st=styles[name]; st.font.name='Arial'; st.font.size=Pt(9.5); st.paragraph_format.space_after=Pt(5); st.paragraph_format.line_spacing=1.08
for name,size,color in [('Title',18,RGBColor(31,56,100)),('Heading 1',14,RGBColor(31,56,100)),('Heading 2',11.5,RGBColor(31,56,100)),('Heading 3',10,RGBColor(70,70,70))]:
    if name in styles:
        st=styles[name]; st.font.name='Arial'; st.font.size=Pt(size); st.font.bold=True; st.font.color.rgb=color; st.paragraph_format.keep_with_next=True; st.paragraph_format.space_before=Pt(10 if name!='Title' else 0); st.paragraph_format.space_after=Pt(5)
for table in doc.tables:
    table.alignment=WD_TABLE_ALIGNMENT.CENTER
    if 'Table Grid' in styles:
        table.style='Table Grid'
    for row_i,row in enumerate(table.rows):
        for cell in row.cells:
            cell.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
            for p in cell.paragraphs:
                p.paragraph_format.space_after=Pt(2); p.paragraph_format.line_spacing=1.0
                for r in p.runs: r.font.name='Arial'; r.font.size=Pt(8.5)
        if row_i==0:
            for cell in row.cells:
                tcPr=cell._tc.get_or_add_tcPr(); shd=OxmlElement('w:shd'); shd.set(qn('w:fill'),'D9E2F3'); tcPr.append(shd)
                for p in cell.paragraphs:
                    for r in p.runs: r.bold=True
for p in doc.paragraphs:
    if p.style and p.style.name in ('Block Text','Quote','Intense Quote'):
        p.paragraph_format.left_indent=Inches(0.22); p.paragraph_format.right_indent=Inches(0.08); p.paragraph_format.space_before=Pt(2); p.paragraph_format.space_after=Pt(4)
        for r in p.runs: r.font.name='Arial'; r.font.size=Pt(9)
    if p.text.startswith('Priority:'):
        for r in p.runs: r.bold=True; r.font.color.rgb=RGBColor(160,0,0)
for p in doc.paragraphs[:6]:
    if p.style and p.style.name=='Title':
        p.alignment=WD_ALIGN_PARAGRAPH.CENTER
        for r in p.runs: r.font.name='Arial'; r.font.size=Pt(19); r.font.bold=True; r.font.color.rgb=RGBColor(31,56,100)
        break
doc.save(path)
PY
parse-doc docx output/spa-markup-memorandum.docx > /tmp/spa-final-check.txt
printf 'parsed-lines='; wc -l < /tmp/spa-final-check.txt
printf 'output-size='; stat -c '%s' output/spa-markup-memorandum.docx","description":"Apply final DOCX formatting and verify","workdir":"/home/agarwaldi/dsh-bench-harness/runs/hv-mixed200-lunahigh-r5-20261116T164249Z/tasks/corporate-ma__draft-markup-of-stock-purchase-agreement-provisions/workspace"}

